<?php include '_header.php';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$slug=strtolower(preg_replace('/[^a-z0-9]+/i','-',$name));$st=$conn->prepare('INSERT INTO categories(name,slug) VALUES(?,?)');$st->bind_param('ss',$name,$slug);$st->execute();}if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$conn->query("DELETE FROM categories WHERE id=$id");header('Location: categories.php');exit;}?><h1>Kategori</h1><div class="panel"><form method="post" style="display:flex;gap:10px"><input class="input" name="name" placeholder="Nama kategori" required><button class="btn">Tambah</button></form><table class="table" style="margin-top:15px"><tr><th>ID</th><th>Nama</th><th>Aksi</th></tr><?php $r=$conn->query('SELECT * FROM categories ORDER BY id DESC');while($c=$r->fetch_assoc()):?><tr><td><?=$c['id']?></td><td><?=htmlspecialchars($c['name'])?></td><td><a href="?delete=<?=$c['id']?>" onclick="return confirmDelete()">Hapus</a></td></tr><?php endwhile;?></table></div><?php include '_footer.php';?>
